mapper.select:
SELECT
    u.username         AS name,
    u.user_profile_url AS profileUrl,
    COALESCE(tp.career, '')               AS description,
    /* 트레이너의 모든 트레이닝에 등록된 수강생 합계 */
    COALESCE((
                 SELECT COUNT(e.enrollment_id)
                 FROM enrollments e
                          JOIN trainings t2 ON e.training_id = t2.training_id
                 WHERE t2.trainer_id = #{trainerId}
             ), 0)                                  AS traineeCount,
    COALESCE(tp.total_average_rating, 0)   AS averageRating,
    /* 자격증 여부 (tp가 없어도 안전) */
    EXISTS (
        SELECT 1 FROM trainer_certificates tc
        WHERE tc.trainer_id = u.user_id
    )                                      AS isCertified
FROM users u
         LEFT JOIN trainer_profiles tp ON u.user_id = tp.trainer_id
WHERE u.user_id = #{trainerId}
